import numpy as np
from statsmodels.tsa.stattools import adfuller

def adf_decision(x, alpha):
    res = adfuller(x, autolag="AIC")
    stat, p = res[0], res[1]
    return round(float(stat), 4), round(float(p), 4), bool(p < alpha)
